BEGIN;
CREATE FUNCTION pg_temp.ok(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label;END IF;RAISE NOTICE 'PASS: %',label;END $$;
SELECT pg_temp.ok(NOT has_function_privilege('anon','public.edv9_last_reconcile_begin(uuid)','EXECUTE'),'anonymous cannot start reconciliation');
SELECT pg_temp.ok(NOT has_function_privilege('authenticated','public.edv9_last_reconcile_page(uuid,uuid,uuid[],integer)','EXECUTE'),'rider cannot write recovery');
SELECT pg_temp.ok(NOT has_function_privilege('service_role','ed_last_stage.redact_expired_synthetic(boolean)','EXECUTE'),'worker cannot trigger redaction');
SELECT pg_temp.ok((SELECT bool_and(relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ed_last_stage' AND c.relkind='r'),'all stage tables have RLS');
SET LOCAL ROLE service_role;
INSERT INTO ed_last_stage.locations(location_id,organization_id,tenant_id,enabled) VALUES('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333',true);
INSERT INTO ed_last_stage.queue_routes(location_id,source_kind,enabled,expires_at) VALUES('11111111-1111-4111-8111-111111111111','synthetic',true,now()+interval '10 minutes');
INSERT INTO ed_last_stage.reconcile_state(location_id,enabled) VALUES('11111111-1111-4111-8111-111111111111',true);
UPDATE ed_last_stage.queue_control SET enabled=true;
DO $$
DECLARE l uuid='11111111-1111-4111-8111-111111111111'; t uuid='44444444-4444-4444-8444-444444444444'; c jsonb;r jsonb; work jsonb;original jsonb;
BEGIN
 PERFORM pg_temp.ok(NOT EXISTS(SELECT 1 FROM ed_last_stage.events WHERE location_id=l),'no webhook received');
 c=public.edv9_last_reconcile_begin(l);PERFORM pg_temp.ok(c IS NOT NULL,'missing-webhook scan can start');
 PERFORM pg_temp.ok(public.edv9_last_claim(l) IS NULL,'poll lease excludes competing full GET');
 PERFORM pg_temp.ok(public.edv9_last_reconcile_begin(l) IS NULL,'second poll excluded');
 r=public.edv9_last_reconcile_page(l,(c->>'lease_token')::uuid,ARRAY[t,t],2);
 PERFORM pg_temp.ok(r->>'state'='completed' AND (r->>'queued')::int=1,'duplicate list IDs produce one queued request');
 PERFORM pg_temp.ok((SELECT ingestion_source='reconciliation' FROM ed_last_stage.events WHERE location_id=l),'internal event is not presented as vendor webhook');
 PERFORM pg_temp.ok(public.edv9_last_reconcile_page(l,(c->>'lease_token')::uuid,ARRAY[t],1)->>'state'='lost_lease','duplicate page completion rejected');
 UPDATE ed_last_stage.locations SET next_request_at='-infinity' WHERE location_id=l;
 work=public.edv9_last_queue_claim(l);PERFORM pg_temp.ok(work IS NOT NULL,'existing durable queue can consume discovery');
 PERFORM pg_temp.ok(public.edv9_last_complete(work->>'event_id',(work->>'lease_token')::uuid,jsonb_build_object('id',t,'locationId',l,'pickupType','ownDelivery','delivery',jsonb_build_object('address','FAKE ONLY'),'customerInfo',jsonb_build_object('name','Synthetic')) )='processed','full tab saved after discovery');
 UPDATE ed_last_stage.reconcile_state SET next_poll_at='-infinity' WHERE location_id=l;
 UPDATE ed_last_stage.locations SET next_request_at='-infinity' WHERE location_id=l;
 c=public.edv9_last_reconcile_begin(l);
 PERFORM public.edv9_last_reconcile_fail(l,(c->>'lease_token')::uuid,'last_rate_limited',120);
 PERFORM pg_temp.ok((SELECT next_request_at>now()+interval '110 seconds' FROM ed_last_stage.locations WHERE location_id=l),'429 delays both polling and full-tab reads');
 PERFORM pg_temp.ok((SELECT next_offset=0 FROM ed_last_stage.reconcile_state WHERE location_id=l),'failed page does not advance cursor');
 UPDATE ed_last_stage.locations SET next_request_at='-infinity' WHERE location_id=l;
 UPDATE ed_last_stage.reconcile_state SET next_poll_at='-infinity' WHERE location_id=l;
 c=public.edv9_last_reconcile_begin(l);UPDATE ed_last_stage.locations SET lease_until=now()-interval '1 second' WHERE location_id=l;
 PERFORM pg_temp.ok(public.edv9_last_reconcile_page(l,(c->>'lease_token')::uuid,ARRAY[t],1)->>'state'='lost_lease','expired worker cannot enqueue');
 UPDATE ed_last_stage.locations SET lease_until=NULL,lease_token=NULL,next_request_at='-infinity' WHERE location_id=l;
 UPDATE ed_last_stage.reconcile_state SET next_poll_at='-infinity',sweep_id=NULL,page_hashes='{}' WHERE location_id=l;
 c=public.edv9_last_reconcile_begin(l);r=public.edv9_last_reconcile_page(l,(c->>'lease_token')::uuid,ARRAY[t],100);
 PERFORM pg_temp.ok(r->>'state'='partial','full page remains partial');
 UPDATE ed_last_stage.locations SET next_request_at='-infinity' WHERE location_id=l;
 UPDATE ed_last_stage.reconcile_state SET next_poll_at='-infinity' WHERE location_id=l;
 c=public.edv9_last_reconcile_begin(l);PERFORM pg_temp.ok((c->>'offset')::int=100,'offset persists for next invocation');
 r=public.edv9_last_reconcile_page(l,(c->>'lease_token')::uuid,ARRAY[t],100);
 PERFORM pg_temp.ok(r->>'state'='stalled' AND (SELECT NOT enabled FROM ed_last_stage.reconcile_state WHERE location_id=l),'repeated full page stops rather than looping');
END $$;
RESET ROLE;
-- Retention acts only on expired, disabled synthetic locations; never production/sandbox.
UPDATE ed_last_stage.queue_routes SET enabled=false,expires_at=now()-interval '1 day' WHERE location_id='11111111-1111-4111-8111-111111111111';
UPDATE ed_last_stage.locations SET enabled=false,lease_token=NULL,lease_until=NULL WHERE location_id='11111111-1111-4111-8111-111111111111';
UPDATE ed_last_stage.events SET received_at=now()-interval '10 days' WHERE location_id='11111111-1111-4111-8111-111111111111';
UPDATE ed_last_stage.snapshots SET fetched_at=now()-interval '10 days' WHERE location_id='11111111-1111-4111-8111-111111111111';
SELECT pg_temp.ok((ed_last_stage.redact_expired_synthetic(false)->>'events')::int=1,'preview identifies only finished old payload');
SELECT pg_temp.ok((ed_last_stage.redact_expired_synthetic(true)->>'enabled')::boolean=false,'destructive cleanup disabled by default');
UPDATE ed_last_stage.retention_control SET synthetic_enabled=true;
DO $$ DECLARE doc jsonb;loc uuid;eid text;result jsonb;BEGIN
 SELECT payload,location_id,event_id INTO doc,loc,eid FROM ed_last_stage.events WHERE state='processed' AND location_id='11111111-1111-4111-8111-111111111111' LIMIT 1;
 result=ed_last_stage.redact_expired_synthetic(true);
 PERFORM pg_temp.ok((result->>'events')::int=1,'finished payload redacted');
 PERFORM pg_temp.ok((result->>'snapshots')::int=0,'snapshot with pending work is not redacted');
 PERFORM pg_temp.ok((SELECT payload='{}'::jsonb AND length(payload_sha256)=64 FROM ed_last_stage.events WHERE event_id=eid),'identity fingerprint survives payload redaction');
 UPDATE ed_last_stage.locations SET enabled=true WHERE location_id=loc;
 PERFORM pg_temp.ok(public.edv9_last_receive(loc,NULL,doc)='duplicate','same event remains duplicate after cleanup');
 BEGIN PERFORM public.edv9_last_receive(loc,NULL,doc||jsonb_build_object('changed',true));RAISE EXCEPTION 'collision not rejected';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'event_id_conflict' THEN RAISE;END IF;END;
 PERFORM pg_temp.ok(true,'changed payload under same identity still rejected');
END $$;
ROLLBACK;
